def icon(name):
 return f'<svg viewBox="0 0 24 24" aria-hidden="true">{ICONS[name]}</svg>'
def link(url, text, cls='text-link', symbol='arrow'):
 return f'<a class="{cls}" href="{url}">{text}{icon(symbol)}</a>'
