focus=''.join(f'<div class="focus-item"><span class="focus-icon">{icon(i)}</span><div><h3>{name}</h3><p>{desc}</p></div></div>' for i,name,desc in [('cloud','Azure & identity','Azure security, Entra ID and hybrid identity.'),('shield','Windows security','Endpoints, Active Directory, Defender and hardening.'),('target','Purple Teaming','Controlled simulations, detection rules and threat hunts.')])
